// Convierte la respuesta del modelo en filas de examen pendientes de verificar.
const doc = $('Juntar para el modelo').first().json;
const salida = [];
for (const item of $input.all()) {
  let bruto = item.json?.content?.[0]?.text ?? '';
  bruto = bruto.replace(/```json/gi, '').replace(/```/g, '').trim();
  let datos;
  try {
    datos = JSON.parse(bruto);
  } catch (error) {
    datos = { preguntas: [{ pregunta: 'REVISAR: respuesta del modelo no parseable', respuesta: bruto.slice(0, 200), apartado: '' }] };
  }
  for (const p of datos.preguntas || []) {
    salida.push({
      json: {
        fecha: new Date().toISOString(),
        id_documento: doc.id_documento,
        documento: doc.titulo,
        pregunta: p.pregunta || '',
        respuesta_propuesta: p.respuesta || '',
        apartado: p.apartado || '',
        verificada: 'no',
      },
    });
  }
}
return salida;

