const doc=$('Trocear en fragmentos').first().json;
const vectors=$input.first().json.data;
if (!Array.isArray(vectors)||vectors.length!==doc.fragmentos.length) throw new Error('Incomplete embeddings');
const mapped=new Map();
for (const v of vectors) {
 if (!Number.isInteger(v.index)||mapped.has(v.index)||!Array.isArray(v.embedding)||v.embedding.length!==1536||!v.embedding.every(Number.isFinite)) throw new Error('Invalid embedding');
 mapped.set(v.index,v.embedding);
}
return [{json:{...doc,fragmentos:doc.fragmentos.map((f,index)=>{if(!mapped.has(index)) throw new Error('Missing embedding index');return {...f,embedding_json:mapped.get(index),modelo_vector:'text-embedding-3-small'};})} }];

const pregunta=String($json.body?.pregunta || '').trim();
const coleccion='REEMPLAZAR_COLECCION';
const dueno='REEMPLAZAR_DUENO';
if (coleccion.startsWith('REEMPLAZAR')||dueno.startsWith('REEMPLAZAR')) throw new Error('Configure trusted collection and owner before enabling query');
if (!pregunta || pregunta.length>4000) throw new Error('Invalid question');
return {json:{pregunta,coleccion,dueno} };

const v=$json.data?.[0]?.embedding;
if (!Array.isArray(v)||v.length!==1536||!v.every(Number.isFinite)) throw new Error('Invalid query embedding');
return {json:{...$('Validar pregunta y ámbito').item.json,embedding:v} };

const sources=typeof $json.fuentes==='string'?JSON.parse($json.fuentes):$json.fuentes;
if (!Array.isArray(sources)) throw new Error('Invalid retrieval result');
const fuentes=sources.map(s=>({documento:s.titulo,id_documento:s.id_documento,apartado:s.apartado,cita:s.texto,similaridad:Number(s.similarity)}));
return {json:{encontrado:fuentes.length>0,respuesta:fuentes.length?fuentes.map((s,i)=>'['+(i+1)+'] '+s.cita).join('\n\n'):'No lo encuentro en la documentación autorizada.',fuentes,metodo:'recuperacion_semantica_con_citas_literales',requiere_revision:true} };
